/* Online modules. All rewarded actions are validated by PostgreSQL. */
const features={overview:null,documents:[],achievements:[],alliances:[],members:[],runs:[],players:[],materials:[],external:[],events:[],goals:[],channel:'geral',messages:[],run:null,runIndex:0,lobby:[],results:null,study:null,busy:false,bankStatus:'all',bankSearch:'',librarySearch:'',libraryKind:'all',libraryLayout:'grid',collection:null,avatarUrls:{},flip:null};
const tierNames=['Quartzo','Ametista','Diamante','Astralita'];
const achievementNames={primeira_questao:'Primeiro passo',dias_luta_gloria:'Dias de luta, dias de glória', '500_acertos':'500 acertos',sinapse20:'Aquece o banco',sinapse40:'Estudante de fato',sinapse60:'Vestibuleiro',sinapse80:'Conexões intensas',sobrecarga:'Sobrecarga',nivel10:'Nível 10',nivel50:'Nível 50',nivel100:'Nível 100','50_porcento':'Meia prova em oito horas',hahahahaha:'Uma prova em um dia'};
const call=(name,...args)=>`${name}(${args.map(a=>esc(JSON.stringify(a))).join(',')})`;
const actionButton=(label,name,args=[],style='')=>`<button class="btn ${style}" onclick="${call(name,...args)}">${esc(label)}</button>`;
const empty=(text='Nenhum registro ainda.')=>`<p class="empty">${esc(text)}</p>`;
const myDocuments=kind=>features.documents.filter(d=>d.kind===kind);
const byId=id=>features.documents.find(d=>d.id===id);
const person=id=>live.profiles.find(p=>p.user_id===id)?.display_name||'Enemizade';
const dateLabel=s=>s?new Date(s).toLocaleString('pt-BR'):'—';
const localDay=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza'}).format(new Date());
function safeLink(s){try{const u=new URL(s);return u.protocol==='https:'?u.href:null;}catch{return null;}}
async function orbitApi(action,p={}){return checked(db.rpc('orbit_api',{action,p}));}
async function loadFeatures(){
 const epoch=live.epoch;
 const names=['documents','achievements','alliances','alliance_members','runs','run_players','materials','external','events','room_goals'];
 const queries=names.map(n=>{let q=db.from('orbit_'+n).select('*');if(n==='achievements')q=q.eq('user_id',live.user.id);if(['events','runs','external'].includes(n))q=q.order('created_at',{ascending:false}).limit(500);return checked(q);});
 const [overview,...data]=await Promise.all([orbitApi('overview'),...queries]);if(epoch!==live.epoch||!live.member)return;
 Object.assign(features,{overview,documents:data[0],achievements:data[1],alliances:data[2],members:data[3],runs:data[4],players:data[5],materials:data[6],external:data[7],events:data[8],goals:data[9]});
 const avatarProfiles=live.profiles.filter(p=>p.avatar_path);if(avatarProfiles.length&&db.storage){const signed=await checked(db.storage.from('orbit-uploads').createSignedUrls(avatarProfiles.map(p=>p.avatar_path),3600));features.avatarUrls=Object.fromEntries(avatarProfiles.map((p,i)=>[p.user_id,signed[i]?.signedUrl]));}
 state.xp=overview.stats.xp;state.points=overview.stats.pr;
 updateAccount();
}
async function guarded(fn){if(features.busy)return;features.busy=true;try{await fn();}catch(e){toast('Não foi possível concluir: '+e.message);}finally{features.busy=false;if(features.run&&['sim','coliseum'].includes(route)&&!$('#modalRoot').children.length)render();}}
async function featureAction(action,p={}){return guarded(async()=>{await orbitApi(action,p);await loadFeatures();render();});}
function field(name,label,value='',type='text',extra=''){return `<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function area(name,label,value='',extra=''){return `<label class="field">${esc(label)}<textarea name="${name}" rows="6" ${extra}>${esc(value)}</textarea></label>`;}
function selectField(name,label,options,value){return `<label class="field">${esc(label)}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function formModal(title,sub,fields,onSave){modal(esc(title),esc(sub),`<form id="onlineForm" class="online-form">${fields}<p id="formError" class="online-error" role="alert"></p><button class="btn primary" type="submit">Salvar</button></form>`);const f=$('#onlineForm');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button[type=submit]');if(b.disabled)return;b.disabled=true;try{await onSave(Object.fromEntries(new FormData(f)),f);await loadFeatures();closeModal();render();}catch(err){const msg=f.querySelector('#formError');if(msg)msg.textContent=err.message;b.disabled=false;}};}
function confirmFeature(title,body,fn){modal(esc(title),esc(body),'<button id="confirmFeature" class="btn primary">Confirmar</button>');$('#confirmFeature').onclick=()=>guarded(async()=>{await fn();await loadFeatures();closeModal();render();});}
function progression(){const s=features.overview?.stats;if(!s)return '';return `<div class="grid4 mb">${stat('Nível',s.level,fmt(s.xp)+' XP permanente','star')}${stat('Patente',tierNames[s.tier],fmt(s.act_pr)+' PR no ato','shield')}${stat('Sinapse',s.synapse+'%', 'Máximo: '+Math.round(s.best_synapse)+'%','bolt')}${stat('Questões',s.correct+s.wrong,s.correct+' acertos','book')}</div>`;}
function featureHome(){const s=features.overview.stats;const next=Math.min(100,s.level+1),target=5*next*next+15*next;return head('Seu espaço de estudos.','Cada sessão conta. Continue de onde parou.')+`<div class="dashboard"><div class="stack"><section class="hero"><div class="hero-text"><span class="eyebrow">SEU UNIVERSO DE POSSIBILIDADES</span><h2 class="serif">Boa sessão, ${esc(live.profile.display_name)}.</h2><p>Um passo de cada vez, mais perto da sua aprovação.</p>${btn('Continuar estudando','data-go="bank"')}</div><div class="orbit-art" aria-hidden="true"><div class="ring"></div><div class="ring"></div><div class="ring"></div><div class="core">${icon('book')}</div><i class="planet"></i><i class="planet second"></i></div></section><section class="card">${section('Seu plano','Tarefas de hoje e pendências','Abrir plano','plan')}${taskRows(true)}</section><div class="grid2"><section class="card">${section('Estudando juntos',live.sessions.length+' em sessão','Entrar','sessions')}<p class="muted">${live.sessions.length?live.sessions.slice(0,4).map(p=>esc(person(p.user_id))).join(', '):'Seja o primeiro a entrar em uma sala.'}</p></section><section class="card">${section('Seu próximo desafio',live.questions.length+' questões no acervo','Praticar','bank')}<p class="muted">${s.correct} acertos registrados. Você já respondeu ${live.attempts.length} questões diferentes no banco.</p></section></div></div><aside class="stack"><section class="card"><div class="profiletop">${avatar(live.user.id)}<div><strong>${esc(live.profile.display_name)}</strong><small>${rankMark(s.tier,'tiny')} ${tierNames[s.tier]} · nível ${s.level}</small></div></div><div class="metrichead"><b class="identity-label">${identityIcon('xp')} Experiência</b><span>${fmt(s.xp)} / ${fmt(target)}</span></div><div class="track"><div class="fill" style="--value:${Math.min(100,s.xp/target*100)}%"></div></div><div class="metrichead mt"><b class="identity-label">${identityIcon('synapse')} Sinapse</b><span>${s.synapse}%</span></div><div class="track"><div class="fill synapse" style="--value:${s.synapse}%"></div></div><p class="muted small mt identity-label">${identityIcon('pr')} ${fmt(s.pr)} PR nesta temporada</p>${actionButton('Ver perfil','go',['profile'],'mt')}</section><section class="card">${section('Conquistas','Seu esforço fica registrado')}${features.achievements.slice(-3).map(a=>`<p class="mt">${icon('star')} ${esc(achievementNames[a.code]||a.code)}</p>`).join('')||'<p class="muted">Seu primeiro marco começa com uma questão.</p>'}</section></aside></div>`;}
function featureRanking(){return head('Ranking','PR da temporada · XP permanente · atos bimestrais')+progression()+`<section class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Posição</th><th>Enemizade</th><th>Patente</th><th>Nível</th><th>PR</th></tr></thead><tbody>${[...features.overview.ranks].sort((a,b)=>b.stats.pr-a.stats.pr||b.stats.xp-a.stats.xp||a.profile.user_id.localeCompare(b.profile.user_id)).map((r,i)=>`<tr><td>${i+1}</td><td>${actionButton(r.profile.display_name,'viewMember',[r.profile.user_id])}</td><td>${tierNames[r.stats.tier]}</td><td>${r.stats.level}</td><td>${fmt(r.stats.pr)}</td></tr>`).join('')}</tbody></table></div></section>${features.overview.config.provisional_thresholds?'<p class="notice mt">Limiares intermediários de patentes provisórios: 2.000 e 7.000 PR. Astralita: 12.000 PR no ato.</p>':''}`;}
async function viewMember(id){await guarded(async()=>{const r=features.overview.ranks.find(r=>r.profile.user_id===id);if(!r)return;const history=await orbitApi('profile_history',{id});modal(esc(r.profile.display_name),`${tierNames[r.stats.tier]} · nível ${r.stats.level}`,`<p>${esc(r.profile.bio||'')}</p><p class="mt">${fmt(r.stats.pr)} PR · ${r.stats.synapse}% de Sinapse</p>${history.length?history.map(e=>`<div class="listline">${esc(e.kind)} · ${e.correct} acertos · ${e.wrong} erros <small>${dateLabel(e.created_at)}</small></div>`).join(''):'<p class="muted mt">Histórico privado ou ainda sem atividades.</p>'}`);});}
function featureSynapse(){return head('Sinapse','Uma questão válida, uma nova conexão. Máximo de 100%.')+progression()+`<section class="card"><h2>Constância faz diferença</h2><p class="mt">A Sinapse diminui com o tempo decorrido, inclusive fora do site. Seu máximo histórico fica registrado. Os marcos são 20%, 40%, 60%, 80% e 100%.</p><p class="muted mt">Respostas repetidas no banco não geram novas recompensas. Questões externas entram depois da validação do administrador.</p></section>`;}
function featureAchievements(){return `<section class="card mt"><h2>Conquistas</h2><div class="grid3 mt">${Object.entries(achievementNames).map(([code,name])=>{const a=features.achievements.find(a=>a.code===code);return `<div class="notice">${icon(a?'star':'lock')} <b>${esc(name)}</b><p class="small mt">${a?'Conquistada em '+dateLabel(a.earned_at):'Ainda não conquistada'}</p></div>`;}).join('')}</div></section>`;}
function featureProfile(){return head('Meu perfil','Identidade, privacidade e histórico de atividades.',actionButton('Sair','logoutOnline'))+progression()+`<section class="card"><div class="row wrap mb">${avatar(live.user.id)}${actionButton('Alterar foto','uploadAvatar')}</div><form id="profileForm" onsubmit="saveOnlineProfile(event)" class="online-form">${field('name','Nome de exibição',live.profile.display_name,'text','required maxlength="40"')}${area('bio','Sobre você',live.profile.bio,'maxlength="500"')}<label><input name="history" type="checkbox" ${live.profile.public_history?'checked':''}> Permitir que os participantes vejam meu histórico de atividades</label><button class="btn primary">Salvar perfil</button></form></section>${featureAchievements()}<section class="card mt"><h2>Histórico recente</h2>${features.events.slice(0,100).map(e=>`<div class="listline"><div><b>${esc(({bank:'Banco de questões',sim:'Simulado',match:'Coliseu',external:'Questões externas',reading:'Leitura',pomodoro:'Pomodoro',flashcards:'Revisão'})[e.kind]||e.kind)}</b><p>${dateLabel(e.created_at)} · ${e.correct} acertos · ${e.wrong} erros</p></div><span>${fmt(e.xp)} XP · ${fmt(e.pr)} PR</span></div>`).join('')||empty()}</section>${features.overview.admin?`<section class="card mt"><h2>Administração</h2>${actionButton('Abrir administração','openAdmin',[],'mt')}</section>`:''}`;}
async function saveOnlineProfile(e){e.preventDefault();const f=e.currentTarget;await guarded(async()=>{const p={display_name:f.elements.name.value.trim(),bio:f.elements.bio.value,public_history:f.elements.history.checked};await checked(db.from('orbit_profiles').update(p).eq('user_id',live.user.id));Object.assign(live.profile,p);await refreshSessions();await loadFeatures();render();toast('Perfil salvo.');});}
function taskRows(short=false){let docs=myDocuments('task').sort((a,b)=>(a.data.order||0)-(b.data.order||0)||String(a.data.date||'').localeCompare(b.data.date||''));if(short)docs=docs.filter(d=>!d.data.done&&(!d.data.date||d.data.date<=localDay())).slice(0,5);return docs.map((d,i)=>`<div class="task ${d.data.done?'done':''}"><button class="taskcheck ${d.data.done?'done':''}" aria-label="Concluir tarefa" onclick="${call('completeTask',d.id)}">${icon('check')}</button><div class="subjectdot"></div><div class="taskbody"><strong>${esc(d.title)}</strong><small>${esc(d.data.subject||'Estudo livre')} · ${esc(d.data.date||'Sem data')} · ${Math.min(Number(d.data.progress)||0,Number(d.data.goal)||1)}/${Number(d.data.goal)||1} · ${esc(d.data.priority||'Normal')}${!d.data.done&&d.data.date<localDay()?' · Pendente':''}</small></div>${actionButton('Editar','editTask',[d.id])}${short?'':actionButton('↑','moveTask',[d.id,-1])+actionButton('↓','moveTask',[d.id,1])}</div>`).join('')||empty('Adicione uma tarefa para organizar seus estudos.');}
function featurePlan(){return head('Meu plano','Metas independentes, prioridades e recorrência.',actionButton('Nova tarefa','editTask',[],'primary'))+`<section class="card">${taskRows()}</section>`;}
function editTask(id){const d=byId(id),v=d?.data||{};formModal(d?'Editar tarefa':'Nova tarefa','Pendências permanecem na data original.',field('title','Título',d?.title,'text','required maxlength="200"')+field('subject','Matéria',v.subject)+field('date','Data',v.date||localDay(),'date','required')+selectField('priority','Prioridade',[['Alta','Alta'],['Normal','Normal'],['Baixa','Baixa']],v.priority||'Normal')+field('goal','Meta',v.goal||1,'number','min="1" max="100000" required')+field('progress','Progresso',v.progress||0,'number','min="0" max="100000" required')+field('repeat','Repetir a cada quantos dias (0 = não repetir)',v.repeat||0,'number','min="0" max="365"')+field('weekdays','Ou dias da semana (0=dom, 1=seg, …, 6=sáb; separados por vírgula)',v.weekdays||'','text','pattern="[0-6](,[0-6])*|"')+area('text','Anotações',v.text),async p=>{await orbitApi('document_save',{id,kind:'task',title:p.title,data:{...v,subject:p.subject,date:p.date,priority:p.priority,goal:+p.goal,progress:+p.progress,repeat:+p.repeat,weekdays:p.weekdays,text:p.text,done:+p.progress>=+p.goal}});});}
async function completeTask(id){await guarded(async()=>{const d=byId(id);const done=!d.data.done;await orbitApi('document_save',{id,kind:'task',title:d.title,data:{...d.data,done,progress:done?Number(d.data.goal)||1:0}});if(done&&(d.data.repeat||d.data.weekdays)&&!myDocuments('task').some(x=>x.data.previous===id)){const date=new Date((d.data.date||localDay())+'T12:00:00Z');if(d.data.weekdays){const days=d.data.weekdays.split(',').map(Number);do{date.setUTCDate(date.getUTCDate()+1);}while(!days.includes(date.getUTCDay()));}else date.setUTCDate(date.getUTCDate()+Number(d.data.repeat));await orbitApi('document_save',{kind:'task',title:d.title,data:{...d.data,previous:id,date:date.toISOString().slice(0,10),done:false,progress:0}});}await loadFeatures();render();});}
async function moveTask(id,dir){await guarded(async()=>{const docs=myDocuments('task').sort((a,b)=>(a.data.order||0)-(b.data.order||0)||String(a.data.date||'').localeCompare(b.data.date||''));const i=docs.findIndex(d=>d.id===id),j=i+dir;if(j<0||j>=docs.length)return;[docs[i],docs[j]]=[docs[j],docs[i]];for(let k=0;k<docs.length;k++)await orbitApi('document_save',{id:docs[k].id,kind:'task',title:docs[k].title,data:{...docs[k].data,order:k}});await loadFeatures();render();});}
function deleteDocument(id){confirmFeature('Excluir registro?','Esta ação remove somente este registro da sua conta.',()=>orbitApi('document_delete',{id}));}
function featureEssays(){return head('Oficina de redação','Rascunhos privados, revisão e histórico na sua conta.',actionButton('Nova redação','editEssay',[],'primary'))+`<div class="grid2">${myDocuments('essay').map(d=>`<section class="card"><h2>${esc(d.title)}</h2><p class="muted mt">${esc(d.data.status||'Rascunho')} · ${d.data.text?.trim().split(/\s+/).filter(Boolean).length||0} palavras</p><p class="small muted mt">Salvo em ${dateLabel(d.updated_at)}</p><div class="row wrap mt">${actionButton('Escrever','editEssay',[d.id])}${actionButton('Excluir','deleteDocument',[d.id])}</div></section>`).join('')||empty('Crie seu primeiro rascunho.')}</div><p class="notice mt">Correção por IA não está habilitada. Você pode registrar sua revisão manual.</p>`;}
function editEssay(id){const d=byId(id);formModal(d?'Continuar redação':'Nova redação','Salve antes de fechar a janela. Seu texto é privado.',field('title','Tema',d?.title,'text','required maxlength="200"')+area('text','Redação',d?.data.text,'maxlength="40000" required')+selectField('status','Etapa',[['Rascunho','Rascunho'],['Revisando','Revisando'],['Concluída','Concluída']],d?.data.status)+area('notes','Minha revisão',d?.data.notes),p=>orbitApi('document_save',{id,kind:'essay',title:p.title,data:{text:p.text,status:p.status,notes:p.notes}}));}
function featureFlashcards(){return head('Flashcards','Revise perguntas e respostas que você criou. Até 100 cartões remunerados por dia; cada cartão conta uma vez no dia.',actionButton('Criar cartão','editCard',[],'primary'))+`<div class="row wrap mb">${studyControls('flashcards')}</div><div class="grid3">${myDocuments('flashcard').map(d=>`<section class="card"><span class="pill purple">${esc(d.data.deck||'Geral')}</span><h2 class="mt">${esc(d.title)}</h2><p class="prewrap mt">${esc(features.flip===d.id?d.data.back:'Pense na resposta antes de virar.')}</p><div class="row wrap mt">${actionButton(features.flip===d.id?'Ocultar':'Virar','flipCard',[d.id])}${features.flip===d.id?actionButton('Lembrei','reviewCard',[d.id,true])+actionButton('Rever','reviewCard',[d.id,false]):''}${actionButton('Editar','editCard',[d.id])}${actionButton('Excluir','deleteDocument',[d.id])}</div><small class="muted">Próxima revisão: ${esc(d.data.due||'Hoje')}</small></section>`).join('')||empty('Crie um cartão com pergunta e resposta.')}</div>`;}
function flipCard(id){features.flip=features.flip===id?null:id;render();}
function editCard(id){const d=byId(id);formModal('Cartão de revisão','Organize seus cartões em baralhos.',field('title','Frente / pergunta',d?.title,'text','required maxlength="200"')+area('back','Verso / resposta',d?.data.back,'required maxlength="10000"')+field('deck','Baralho',d?.data.deck||'Geral'),p=>orbitApi('document_save',{id,kind:'flashcard',title:p.title,data:{...d?.data,back:p.back,deck:p.deck}}));}
async function reviewCard(id,remembered){features.flip=null;await featureAction('flashcard_review',{id,remembered});}
function studyControls(kind){return features.study?`<span class="pill purple">Atividade em andamento</span>${actionButton('Encerrar e registrar tempo','finishStudy',[],'primary')}`:actionButton('Iniciar tempo de estudo','startStudy',[kind],'primary');}
async function startStudy(kind){await guarded(async()=>{features.study=await orbitApi('study_start',{kind});features.study.kind=kind;if(!$('#modalRoot').children.length)render();toast('Tempo iniciado. Mantenha a página visível enquanto estuda.');});}
async function finishStudy(){await guarded(async()=>{if(!features.study)return;await orbitApi('study_tick',{id:features.study.id,finish:true});features.study=null;await loadFeatures();if(!$('#modalRoot').children.length)render();toast('Tempo registrado.');});}
function featurePomodoro(){return head('Um tempo para focar.','O relógio e seus controles ficam na Ilha Dinâmica.')+`<section class="card"><h2>Seu foco, no seu ritmo</h2><p class="muted mt">Foco de 25 minutos, pausa de 5 e pausa longa de 15 a cada quatro ciclos. Você confirma a próxima etapa.</p><div class="row wrap mt">${actionButton('Abrir controles na ilha','expandIsland',[true],'primary')}</div></section><section class="card mt"><h2>Registrar este estudo</h2><p class="muted mt">Inicie o registro junto com sua atividade. O tempo registrado avança enquanto a página está visível. Encerre ao fazer uma pausa.</p><div class="row wrap mt">${studyControls('pomodoro')}</div><p class="small muted mt">Pomodoro não concede PR. XP de foco usa parâmetro provisório de teste.</p></section>`;}
function featureLibrary(trails=false){const collection=byId(features.collection);const list=features.materials.filter(m=>(!collection||(collection.data.ids||[]).includes(m.id))&&(trails?m.kind==='trail':m.kind!=='trail')&&(!features.librarySearch||(m.title+' '+m.subject).toLowerCase().includes(features.librarySearch.toLowerCase())));return head(trails?'Trilhas de conteúdo':'Biblioteca','Conteúdo publicado pela administração, com progresso salvo.')+`<section class="card mb"><label>Buscar<input aria-label="Buscar material" value="${esc(features.librarySearch)}" onchange="features.librarySearch=this.value;render()"></label><div class="row wrap mt">${actionButton('Grade / lista','toggleLibraryLayout')}${actionButton('Nova coleção','editCollection')}${features.overview.admin?actionButton('Publicar material','editMaterial'):''}</div><div class="row wrap mt">${actionButton('Todos os materiais','filterCollection',[null])}${myDocuments('collection').map(d=>actionButton(d.title,'filterCollection',[d.id])).join('')}${collection?actionButton('Editar coleção','editCollection',[collection.id]):''}</div></section><div class="${features.libraryLayout==='grid'?'grid3':'stack'}">${list.map(m=>`<section class="card featurecard"><div class="resource-cover">${icon(m.kind==='video'?'play':m.kind==='trail'?'map':'file')}</div><span class="pill purple">${esc(m.subject)}</span><h2>${esc(m.title)}</h2><p>${esc(m.kind)} · atualizado ${new Date(m.updated_at).toLocaleDateString('pt-BR')}</p>${actionButton('Abrir','openMaterial',[m.id],'primary')}${actionButton('Adicionar à coleção','addToCollection',[m.id])}</section>`).join('')||empty('Nenhum material publicado para este filtro.')}</div>`;}
function editMaterial(id){const m=features.materials.find(m=>m.id===id);formModal('Publicar material','Somente a administração publica conteúdo para todos.',field('title','Título',m?.title,'text','required maxlength="200"')+field('subject','Matéria',m?.subject||'Geral')+selectField('kind','Formato',[['text','Texto'],['pdf','PDF por endereço HTTPS'],['video','Vídeo por endereço HTTPS'],['trail','Trilha de estudo']],m?.kind||'text')+field('url','Endereço HTTPS (PDF ou vídeo)',m?.url||'','url')+area('body','Conteúdo / etapas da trilha',m?.body,'maxlength="100000"'),p=>{if(['pdf','video'].includes(p.kind)&&!safeLink(p.url))throw Error('Informe um endereço HTTPS válido.');return orbitApi('admin',{operation:'material_save',id,...p});});}
async function openMaterial(id){const m=features.materials.find(m=>m.id===id);if(!m)return;const progress=myDocuments('progress').find(d=>d.data.material===id);const url=safeLink(m.url);let content=`<div class="prewrap reading-text">${esc(m.body)}</div>`;if(m.kind==='pdf'&&url)content+=`<p class="mt"><a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(url)}">Abrir PDF</a></p><p class="muted small mt">Use o leitor do navegador para pesquisar e navegar nas páginas.</p>`;if(m.kind==='video'&&url)content+=`<video id="materialVideo" controls preload="metadata" src="${esc(url)}" style="width:100%"></video><p><a target="_blank" rel="noopener noreferrer" href="${esc(url)}">Abrir fonte do vídeo</a></p>`;modal(esc(m.title),esc(m.subject),content+`<div class="row wrap mt">${studyControls('reading')}${actionButton('Destacar seleção','highlightSelection')}</div>${progress?.data.highlight?`<mark class="prewrap">${esc(progress.data.highlight)}</mark>`:''}<form id="materialProgress" class="online-form mt">${field('position',m.kind==='video'?'Posição em segundos':'Página / etapa',progress?.data.position||0,'number','min="0" max="100000"')}${area('notes','Minhas anotações',progress?.data.notes)}${area('highlight','Trecho destacado',progress?.data.highlight)}<label><input name="done" type="checkbox" ${progress?.data.done?'checked':''}> Concluído</label><button class="btn primary">Salvar progresso</button></form><div class="row wrap mt">${actionButton('Foi útil','voteMaterial',[id,true])}${actionButton('Não foi útil','voteMaterial',[id,false])}${features.overview.admin?actionButton('Editar material','editMaterial',[id]):''}</div>`);const video=$('#materialVideo');if(video){video.addEventListener('loadedmetadata',()=>{video.currentTime=Number(progress?.data.position)||0;});video.addEventListener('timeupdate',()=>{$('#materialProgress').elements.position.value=Math.floor(video.currentTime);});}$('#materialProgress').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await guarded(async()=>{await orbitApi('document_save',{id:progress?.id,kind:'progress',title:m.title,data:{material:id,position:Number(f.elements.position.value),notes:f.elements.notes.value,highlight:f.elements.highlight.value,done:f.elements.done.checked}});await loadFeatures();toast('Progresso salvo.');});};}
async function voteMaterial(id,helpful){await guarded(async()=>{await orbitApi('material_vote',{id,helpful});toast('Avaliação salva.');});}
function myAlliance(){return features.members.find(m=>m.user_id===live.user.id)?.alliance_id;}
function featureAlliances(){const mine=myAlliance();return head('Alianças e ligas','Um grupo por participante. Os pontos ficam com a aliança em que foram conquistados.',mine?actionButton('Sair da aliança','leaveAlliance'):actionButton('Criar aliança','createAlliance',[],'primary'))+`<div class="grid2">${features.alliances.map(a=>{const members=features.members.filter(m=>m.alliance_id===a.id),score=features.overview.alliance_scores.find(s=>s.alliance_id===a.id)||{};return `<section class="card"><span class="pill purple">${esc(a.tag)}</span><h2 class="mt">${esc(a.name)}</h2><p class="muted mt">${esc(a.description)}</p><p class="mt">${fmt(score.pr||0)} PR permanente · ${fmt(score.week_pr||0)} nesta semana</p><p class="small muted">${members.length} integrantes · líder: ${esc(person(a.leader))}</p><div class="row wrap mt">${mine===a.id?actionButton('Chat da aliança','openOnlineChat',['alliance:'+a.id]):!mine?actionButton('Entrar','featureAction',['alliance_join',{id:a.id}],'primary'):''}${members.map(m=>actionButton(person(m.user_id),'viewMember',[m.user_id])).join('')}${a.leader===live.user.id?actionButton('Gerenciar','manageAlliance',[a.id]):''}</div></section>`;}).join('')||empty('Crie a primeira aliança.')}</div>`;}
function createAlliance(){formModal('Criar aliança','Você será o líder do grupo.',field('name','Nome','','text','required minlength="2" maxlength="40"')+field('tag','Sigla','','text','required minlength="2" maxlength="6"')+area('description','Descrição','','maxlength="500"'),p=>orbitApi('alliance_create',p));}
function leaveAlliance(){confirmFeature('Sair da aliança?','Os pontos anteriores continuam atribuídos ao grupo.',()=>orbitApi('alliance_leave'));}
function manageAlliance(id){const a=features.alliances.find(a=>a.id===id);modal(esc(a.name),'Gerenciar integrantes e liderança.',features.members.filter(m=>m.alliance_id===id&&m.user_id!==live.user.id).map(m=>`<div class="listline"><b>${esc(person(m.user_id))}</b>${actionButton('Remover','allianceManage',[id,'remove',m.user_id])}${actionButton('Transferir liderança','allianceManage',[id,'transfer',m.user_id])}</div>`).join('')+actionButton('Excluir aliança','allianceManage',[id,'delete'],'mt'));}
function allianceManage(id,operation,user_id){confirmFeature('Confirmar alteração na aliança?','A alteração será aplicada a este grupo.',()=>orbitApi('alliance_manage',{id,operation,user_id}));}
function chatChannels(){return [['geral','Comunidade'],['Banco de questões','Banco de questões'],['Correção','Correção'],['Outro','Outro'],...(myAlliance()?[['alliance:'+myAlliance(),'Minha aliança']]:[])];}
async function fetchMessages(){const epoch=live.epoch,channel=features.channel;const data=await checked(db.from('orbit_messages').select('*').eq('channel',channel).order('created_at',{ascending:false}).limit(30));if(epoch!==live.epoch||channel!==features.channel)return;features.messages=data.reverse();paintChat();}
function paintChat(){const log=$('#communitylog');if(!log||$('#communitychat').classList.contains('hidden'))return;const snapshot=JSON.stringify(features.messages);if(log.dataset.snapshot===snapshot)return;const nearEnd=log.scrollHeight-log.scrollTop-log.clientHeight<50;log.dataset.snapshot=snapshot;log.innerHTML=features.messages.map(m=>`<div class="bubble"><b>${esc(person(m.user_id))}</b><p class="prewrap">${esc(m.body)}</p><small>${new Date(m.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small> ${m.user_id===live.user.id||features.overview.admin?actionButton('Excluir','deleteMessage',[m.id]):actionButton('Denunciar','reportContent',['message:'+m.id])}</div>`).join('')||'<p class="muted">Nenhuma mensagem hoje.</p>';if(nearEnd)log.scrollTop=log.scrollHeight;}
async function openOnlineChat(channel='geral'){features.channel=channel;const el=$('#communitychat');el.innerHTML=`<div class="between mb"><h3>Converse com suas enemizades</h3><button class="circlebtn" onclick="toggleChat()" aria-label="Fechar chat">${icon('x')}</button></div><select aria-label="Canal do chat" onchange="openOnlineChat(this.value)">${chatChannels().map(([id,n])=>`<option value="${esc(id)}" ${id===channel?'selected':''}>${esc(n)}</option>`).join('')}</select><p class="muted small mt mb">Até 30 mensagens do dia · horário de Fortaleza</p><div class="chatlog" id="communitylog" role="log" aria-live="polite"></div><form class="chatinput" onsubmit="sendOnlineMessage(event)"><input id="communitymessage" placeholder="Escreva uma mensagem…" aria-label="Mensagem" required maxlength="1000"><button class="btn primary" aria-label="Enviar mensagem">${icon('send')}</button></form><p id="chatError" class="online-error small"></p>`;el.classList.remove('hidden');try{await fetchMessages();$('#communitymessage')?.focus();}catch(e){$('#chatError').textContent=e.message;}}
toggleChat=function(){if($('#communitychat').classList.contains('hidden'))openOnlineChat(features.channel);else $('#communitychat').classList.add('hidden');};
async function sendOnlineMessage(e){e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),input=f.querySelector('input');if(b.disabled)return;b.disabled=true;try{await orbitApi('chat_send',{channel:features.channel,body:input.value});input.value='';await fetchMessages();$('#chatError').textContent='';}catch(err){$('#chatError').textContent=err.message;}finally{b.disabled=false;}}
async function deleteMessage(id){await guarded(async()=>{await orbitApi('chat_delete',{id});await fetchMessages();});}
function reportContent(target){formModal('Denunciar conteúdo','O administrador receberá sua denúncia.',area('reason','Motivo','','required minlength="3" maxlength="1000"'),p=>orbitApi('report',{target,reason:p.reason}));}
function featureSessions(){return head('Estudando em companhia.','Participantes reais · saída após 30 minutos sem atividade registrada.')+`<div class="grid3">${['Banco de questões','Correção','Outro'].map(room=>{const ps=live.sessions.filter(s=>s.room===room),goal=features.goals.find(g=>g.room===room);return `<section class="card"><h2>${room}</h2><p class="muted mt mb">${ps.length} ${ps.length===1?'participante':'participantes'}</p>${ps.map(s=>`<div class="listline"><span class="avatar">${esc(person(s.user_id).slice(0,2))}</span><div><strong>${esc(person(s.user_id))}</strong><p>Desde ${new Date(s.started_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</p>${s.options?.goal?`<p>Meta pessoal: ${esc(s.options.goal)}</p>`:''}</div></div>`).join('')||'<p class="muted">Sala livre.</p>'}<div class="row wrap mt">${actionButton(live.sessions.some(s=>s.user_id===live.user.id&&s.room===room)?'Sair da sala':'Entrar','joinSession',[room],'primary')}${actionButton('Conversar','openOnlineChat',[room])}</div><p class="muted small mt">Meta coletiva: ${goal?goal.goal+' questões':'não definida'}</p>${live.sessions.some(s=>s.user_id===live.user.id&&s.room===room)?actionButton('Ajustar metas','sessionGoals',[room],'mt'):''}</section>`;}).join('')}</div>`;}
function sessionGoals(room){const s=live.sessions.find(s=>s.user_id===live.user.id),g=features.goals.find(g=>g.room===room);formModal('Metas da sessão','Sua meta é pessoal; a meta coletiva fica visível à sala.',field('personal','Minha meta',s?.options?.goal||'','text','maxlength="100"')+field('collective','Meta coletiva de questões',g?.goal||45,'number','required min="1" max="100000"'),async p=>{await orbitApi('session_options',{options:{goal:p.personal}});await orbitApi('room_goal',{room,goal:+p.collective});await refreshSessions();});}
function runLabel(status){return ({waiting:'Aguardando',active:'Em andamento',finished:'Finalizada',cancelled:'Cancelada'})[status]||status;}
function featureRuns(kind){if(features.run&&features.run.kind===kind)return runScreen();return head(kind==='match'?'Coliseu':'Simulados',kind==='match'?'Mesmas questões e prazo para todos. Até oito participantes.':'Responda sem gabarito e revise ao finalizar.',actionButton(kind==='match'?'Criar partida':'Criar simulado','createRun',[kind],'primary'))+`<div class="grid2">${features.runs.filter(r=>r.kind===kind).map(r=>`<section class="card"><span class="pill purple">${runLabel(r.status)}</span><h2 class="mt">${esc(r.title||'Prova de estudo')}</h2><p class="muted mt">${r.question_ids.length} questões · ${r.seconds/60} minutos · ${esc(person(r.owner_id))}</p>${actionButton('Abrir','openRun',[r.id],'mt primary')}</section>`).join('')||empty('Crie uma prova para começar.')}</div><p class="notice mt">${kind==='match'?'Quem acerta mais vence; em igualdade de acertos, vale o menor tempo. O PR desta versão de testes usa um multiplicador provisório de 2.':'A correção aparece somente após encerrar a prova. Questões em branco não concedem XP, PR nem Sinapse.'}</p>`;}
function createRun(kind){formModal(kind==='match'?'Criar partida':'Criar simulado','A quantidade se limita às questões disponíveis no filtro.',field('title','Nome','','text','required maxlength="100"')+field('count','Questões',Math.min(10,live.questions.length),'number','required min="1" max="180"')+field('minutes','Duração em minutos',30,'number','required min="1" max="360"')+selectField('discipline','Área',[['','Todas'],...Object.entries(areaNames)],''),async p=>{const r=await orbitApi('run_create',{kind,title:p.title,count:+p.count,seconds:+p.minutes*60,discipline:p.discipline});await loadFeatures();features.run=features.runs.find(x=>x.id===r.id);features.runIndex=0;features.results=null;features.lobby=await orbitApi('lobby',{id:r.id});});}
async function openRun(id){await guarded(async()=>{await loadFeatures();features.run=features.runs.find(r=>r.id===id);if(!features.run)throw Error('Prova indisponível.');features.runIndex=0;features.results=null;await refreshRun();render();});}
async function refreshRun(){if(!features.run)return;const id=features.run.id;const [r,players,lobby]=await Promise.all([checked(db.from('orbit_runs').select('*').eq('id',id).single()),checked(db.from('orbit_run_players').select('*').eq('run_id',id)),orbitApi('lobby',{id})]);if(features.run?.id!==id)return;features.run=r;features.players=features.players.filter(p=>p.run_id!==id).concat(players);features.lobby=lobby;const mine=players.find(p=>p.user_id===live.user.id);if(r.status==='finished'&&mine)features.results=await orbitApi('run_results',{id});}
function runScreen(){const r=features.run,mine=features.players.find(p=>p.run_id===r.id&&p.user_id===live.user.id),q=live.questions.find(q=>q.id===r.question_ids[features.runIndex]);const accepted=features.lobby.filter(p=>p.status==='accepted');let html=head(esc(r.title),`${r.question_ids.length} questões · ${runLabel(r.status)}`,actionButton('Voltar à lista','closeRun'));
 if(r.status==='waiting')return html+`<section class="card"><h2>Sala de espera</h2>${features.lobby.map(p=>`<div class="listline"><b>${esc(person(p.user_id))}</b><span>${esc(({accepted:'Confirmado',invited:'Convidado',declined:'Recusou'})[p.status]||p.status)}</span></div>`).join('')}<div class="row wrap mt">${mine?.status!=='accepted'&&r.kind==='match'?actionButton('Aceitar / entrar','runAction',['run_join'],'primary'):''}${mine&&mine.user_id!==r.owner_id?actionButton('Recusar / sair','runAction',['run_decline']):''}${r.owner_id===live.user.id?actionButton('Iniciar prova','runAction',['run_start'],'primary')+actionButton('Cancelar prova','cancelRun'):''}</div>${r.owner_id===live.user.id&&r.kind==='match'?`<form class="row mt" onsubmit="inviteRun(event)"><select name="user_id" aria-label="Convidar participante">${live.profiles.filter(p=>p.user_id!==live.user.id).map(p=>`<option value="${p.user_id}">${esc(p.display_name)}</option>`).join('')}</select><button class="btn">Convidar</button></form>`:''}<p class="muted small mt">${accepted.length} confirmado(s). Quem ainda não aceitou fica fora quando a prova começa.</p></section>`;
 if(r.status==='cancelled')return html+empty('Esta prova foi cancelada.');
 if(r.status==='finished')return html+runResults();
 if(!mine||mine.status!=='accepted')return html+`<section class="card"><p>${mine?.status==='finished'?'Sua participação foi salva. Aguarde os demais participantes ou o fim do prazo.':'Você não está participando desta prova.'}</p><p class="mt" id="runClock"></p>${actionButton('Atualizar','refreshRunView',[],'mt')}</section>`;
 if(!q)return html+empty('Não foi possível carregar esta questão. Atualize a página.');
 const chosen=mine.answers[q.id];return html+`<section class="card"><div class="between"><span>${features.runIndex+1} / ${r.question_ids.length}</span><strong id="runClock"></strong></div><div class="question mt">${richText(q.context)}<p class="mt">${richText(q.prompt)}</p></div><div class="options">${q.alternatives.map(a=>`<button class="option ${chosen===a.letter?'chosen':''}" ${features.busy?'disabled':''} onclick="${call('answerRun',q.id,a.letter)}"><b>${a.letter}</b><span>${richText(a.text)}${safeImage(a.file)?`<img src="${esc(a.file)}" alt="Imagem da alternativa ${a.letter}">`:''}</span></button>`).join('')}</div><p class="muted small mt">${chosen?'Resposta '+esc(chosen)+' salva.':'Selecione uma alternativa para salvar.'} · ${Object.keys(mine.answers).length} respondidas</p><div class="row wrap mt">${actionButton('Anterior','moveRun',[-1])}${actionButton('Próxima','moveRun',[1])}${actionButton('Finalizar prova','confirmFinishRun',[],'primary')}</div></section>`;
}
function closeRun(){features.run=null;features.results=null;render();}
async function refreshRunView(){await guarded(async()=>{await refreshRun();render();});}
function moveRun(d){features.runIndex=Math.max(0,Math.min(features.run.question_ids.length-1,features.runIndex+d));render();}
async function runAction(action){await guarded(async()=>{await orbitApi(action,{id:features.run.id});await refreshRun();await loadFeatures();render();});}
async function inviteRun(e){e.preventDefault();const id=e.currentTarget.elements.user_id.value;if(id)await guarded(async()=>{await orbitApi('run_invite',{id:features.run.id,user_id:id});await refreshRun();render();});}
function cancelRun(){confirmFeature('Cancelar esta prova?','Só é possível cancelar antes do início.',async()=>{await orbitApi('run_cancel',{id:features.run.id});await refreshRun();});}
async function answerRun(question_id,choice){await guarded(async()=>{await orbitApi('run_answer',{id:features.run.id,question_id,choice});const mine=features.players.find(p=>p.run_id===features.run.id&&p.user_id===live.user.id);mine.answers[question_id]=choice;render();});}
function confirmFinishRun(){confirmFeature('Finalizar a prova?','Questões em branco não geram recompensa. A finalização não pode ser desfeita.',async()=>{await orbitApi('run_finish',{id:features.run.id});await refreshRun();});}
function runResults(){if(!features.results)return empty('Correção disponível somente para quem participou.');const result=features.results,players=[...result.players].filter(p=>p.status==='finished').sort((a,b)=>b.correct-a.correct||a.elapsed-b.elapsed),mine=players.find(p=>p.user_id===live.user.id);return `<section class="card"><h2>Resultado</h2>${players.map((p,i)=>`<div class="listline"><b>${i&&p.correct===players[i-1].correct&&p.elapsed===players[i-1].elapsed?'Empate':i+1} · ${esc(person(p.user_id))}</b><span>${p.correct} acertos · ${Math.floor(p.elapsed/60)}min ${p.elapsed%60}s</span></div>`).join('')}</section><section class="card mt"><h2>Correção</h2>${features.run.question_ids.map(id=>{const q=live.questions.find(q=>q.id===id);return `<details class="mt"><summary>Questão ${q?.number||id} · ${mine?.answers[id]===result.keys[id]?'Acerto':'Erro'} · gabarito ${esc(result.keys[id])}</summary><div class="question mt">${richText(q?.context)}${richText(q?.prompt)}${q?.alternatives.map(a=>`<p class="mt"><b>${a.letter}</b> ${richText(a.text)}${safeImage(a.file)?`<img src="${esc(a.file)}" alt="Alternativa ${a.letter}">`:''}</p>`).join('')||''}<p class="mt">Sua resposta: ${esc(mine?.answers[id]||'Em branco')}</p></div></details>`;}).join('')}</section>`;}
function featureExternal(){return head('Questões externas','Registre estudos feitos fora do Orbit. Recompensas após validação.',actionButton('Registrar lote','addExternal',[],'primary'))+`<section class="card">${features.external.filter(e=>e.user_id===live.user.id).map(e=>`<div class="listline"><div><b>${esc(e.source)}</b><p>${e.correct} acertos · ${e.wrong} erros · ${dateLabel(e.created_at)}</p><p>${esc(e.review_note)}</p></div><span class="pill purple">${({pending:'Em análise',approved:'Aprovado',rejected:'Não aprovado'})[e.status]}</span>${e.proof_path?actionButton('Comprovante','viewProof',[e.proof_path]):''}</div>`).join('')||empty()}</section>`;}
function addExternal(){formModal('Registrar questões','Anexe uma imagem ou PDF de até 5 MB. A administração valida o registro.',field('source','Fonte / atividade','','text','required maxlength="200"')+field('correct','Acertos',0,'number','required min="0" max="10000"')+field('wrong','Erros',0,'number','required min="0" max="10000"')+'<label class="field">Comprovante<input name="proof" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" required></label>',async(p,f)=>{const file=f.elements.proof.files[0];if(file.size>5242880)throw Error('O arquivo deve ter até 5 MB.');const path=live.user.id+'/proof/'+crypto.randomUUID();await checked(db.storage.from('orbit-uploads').upload(path,file,{contentType:file.type}));try{await orbitApi('external_add',{source:p.source,correct:+p.correct,wrong:+p.wrong,proof_path:path});}catch(e){await db.storage.from('orbit-uploads').remove([path]);throw e;}});}
async function viewProof(path){await guarded(async()=>{const data=await checked(db.storage.from('orbit-uploads').createSignedUrl(path,120));modal('Comprovante','O endereço expira em dois minutos.',`<a class="btn primary" href="${esc(data.signedUrl)}" target="_blank" rel="noopener noreferrer">Abrir arquivo</a>`);});}
async function openAdmin(){await guarded(async()=>{const [members,reports]=await Promise.all([orbitApi('admin',{operation:'members'}),checked(db.from('orbit_reports').select('*').eq('resolved',false).order('created_at',{ascending:false}))]);modal('Administração','Gerencie o acesso ao piloto, registros externos e denúncias.',`<h3>Contas</h3>${members.map(m=>`<div class="listline"><div><b>${esc(m.email)}</b><p>${m.allowed?'Autorizada':'Aguardando autorização'}</p></div>${m.id!==live.user.id?actionButton(m.allowed?'Revogar':'Autorizar','adminMember',[m.id,!m.allowed]):''}</div>`).join('')}<h3 class="mt">Registros externos</h3>${features.external.filter(e=>e.status==='pending').map(e=>`<div class="listline"><div><b>${esc(person(e.user_id))} · ${esc(e.source)}</b><p>${e.correct} acertos · ${e.wrong} erros</p><div class="row wrap">${e.proof_path?actionButton('Comprovante','viewProof',[e.proof_path]):''}${actionButton('Analisar','reviewExternal',[e.id])}</div></div></div>`).join('')||'<p class="muted mt">Nenhum pendente.</p>'}<h3 class="mt">Denúncias</h3>${reports.map(r=>`<div class="listline"><div><b>${esc(r.target)}</b><p>${esc(r.reason)}</p></div>${actionButton('Resolvida','adminResolve',[r.id])}</div>`).join('')||'<p class="muted mt">Nenhuma pendente.</p>'}<h3 class="mt">Conteúdo e dados</h3><div class="row wrap mt">${actionButton('Publicar material','editMaterial')}${actionButton('Exportar dados administrativos','exportAdminData')}</div><p class="notice mt">A limpeza para o lançamento ainda não foi executada. Não há botão de apagar todo o ambiente nesta versão.</p>`);});}
async function adminMember(user_id,allow){await guarded(async()=>{await orbitApi('admin',{operation:allow?'allow':'revoke',user_id});toast('Acesso atualizado.');});await openAdmin();}
async function adminResolve(id){await guarded(async()=>{await orbitApi('admin',{operation:'resolve',id});});await openAdmin();}
function reviewExternal(id){formModal('Analisar registro','A aprovação concede a recompensa uma única vez.',selectField('approve','Decisão',[['true','Aprovar'],['false','Não aprovar']],'true')+area('note','Observação','','maxlength="1000"'),p=>orbitApi('admin',{operation:'review',id,approve:p.approve==='true',note:p.note}));}
async function exportAdminData(){await guarded(async()=>{const data=await orbitApi('admin',{operation:'export'});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='enemizades-backup-administrativo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
const pilotBank=liveBank;
activeQuestions=function(){return live.questions.filter(q=>(live.filter==='Todas'||q.discipline===live.filter)&&(!features.bankSearch||(q.context+' '+q.prompt+' '+q.number).toLowerCase().includes(features.bankSearch.toLowerCase()))&&(features.bankStatus==='all'||features.bankStatus==='new'&&!ownAttempt(q)||features.bankStatus==='wrong'&&ownAttempt(q)&&!ownAttempt(q).is_correct||features.bankStatus==='saved'&&myDocuments('favorite').some(d=>d.data.question===q.id)));};
function featureBank(){const active=features.runs.find(r=>r.status==='active'&&features.players.some(p=>p.run_id===r.id&&p.user_id===live.user.id&&p.status==='accepted'));if(active)return head('Uma prova está em andamento','Finalize sua participação para retornar ao banco.')+actionButton('Retomar prova','resumeActiveRun',[active.id],'primary');const filters=`<section class="card mb"><div class="formgrid"><label>Buscar por texto ou número<input value="${esc(features.bankSearch)}" onchange="features.bankSearch=this.value;live.index=0;render()"></label><label>Mostrar<select onchange="features.bankStatus=this.value;live.index=0;render()">${[['all','Todas'],['new','Não respondidas'],['wrong','Erros'],['saved','Favoritas']].map(([id,label])=>`<option value="${id}" ${features.bankStatus===id?'selected':''}>${label}</option>`).join('')}</select></label></div></section>`;live.index=Math.min(live.index,Math.max(0,activeQuestions().length-1));const q=currentLiveQuestion();let html=pilotBank().replace('ENEM 2023 · acervo inicial do piloto','Acervo ENEM · respostas e recompensas salvas na conta').replaceAll('pontos de teste registrados','XP registrados');return filters+html+(q?`<div class="row wrap mt">${actionButton(myDocuments('favorite').some(d=>d.data.question===q.id)?'Remover favorita':'Favoritar','favoriteQuestion',[q.id])}${actionButton('Relatar problema','reportContent',['question:'+q.id])}</div>`:'');}
async function favoriteQuestion(id){const d=myDocuments('favorite').find(d=>d.data.question===id);await featureAction(d?'document_delete':'document_save',d?{id:d.id}:{kind:'favorite',title:'Questão favorita',data:{question:id}});}
async function resumeActiveRun(id){const r=features.runs.find(r=>r.id===id);route=r.kind==='match'?'coliseum':'sim';await openRun(id);}
const submitPilotAnswer=submitLiveAnswer;
submitLiveAnswer=async function(){await submitPilotAnswer();if(!live.error){try{await loadFeatures();render();}catch(e){toast('Resposta salva; atualização do progresso pendente.');}}};
const originalSettings=settings;
function featureSettings(){return originalSettings().replace(/<section class="card" style="grid-column:1\/-1">[\s\S]*?<\/section><\/div>$/,`<section class="card" style="grid-column:1/-1"><h2>Orbit · ambiente de testes</h2><p class="muted mt">Os dados de estudo ficam na sua conta. As preferências visuais ficam neste navegador. IA permanece desativada.</p><div class="row wrap mt">${features.overview.admin?actionButton('Administração','openAdmin'):''}</div></section></div>`);}
views.ai=()=>head('Assistente IA','Integração reservada para uma próxima etapa.')+'<section class="card"><h2>Continue estudando</h2><p class="muted mt">Nenhuma resposta de IA é simulada nesta versão. Use o banco e os materiais disponíveis.</p>'+btn('Abrir questões','data-go="bank"','primary mt')+'</section>';
Object.assign(views,{home:featureHome,bank:featureBank,profile:featureProfile,ranking:featureRanking,synapse:featureSynapse,plan:featurePlan,essay:featureEssays,flashcards:featureFlashcards,pomodoro:featurePomodoro,library:()=>featureLibrary(false),trails:()=>featureLibrary(true),alliances:featureAlliances,sessions:featureSessions,sim:()=>featureRuns('sim'),coliseum:()=>featureRuns('match'),external:featureExternal,settings:featureSettings});
const oldAccountUpdate=updateAccount;
updateAccount=function(){oldAccountUpdate();const s=features.overview?.stats;const label=$('.account small');if(label&&s)label.textContent=tierNames[s.tier]+' · nível '+s.level;$('.sidefoot .version').textContent='Orbit · testes online 0.2';document.querySelectorAll('.topbar .avatar').forEach(e=>e.textContent=live.profile.display_name.slice(0,2));const image=features.avatarUrls[live.user.id];if(image)document.querySelectorAll('.account .avatar,.topbar .avatar').forEach(e=>e.innerHTML=`<img src="${esc(image)}" alt="">`);};
const css=document.createElement('link');css.rel='stylesheet';css.href='assets/features.css?v=0.2.1';document.head.append(css);
document.querySelectorAll('[data-go="flashcards"] .navbadge').forEach(e=>e.remove());
document.querySelectorAll('.demo').forEach(e=>e.textContent='AMBIENTE DE TESTES');
$('.float-chat').classList.remove('hidden');$('#communitylog').innerHTML='';
let pollRunning=false;
setInterval(async()=>{if(!live.member||document.hidden||pollRunning)return;pollRunning=true;try{if(!$('#communitychat').classList.contains('hidden'))await fetchMessages();if(features.run&&!features.busy){const before=JSON.stringify([features.run,features.lobby,features.results]);await refreshRun();if(before!==JSON.stringify([features.run,features.lobby,features.results])&&!$('#onlineForm'))render();}}catch(e){/* Next poll retries without clearing current content. */}finally{pollRunning=false;}},8000);
setInterval(async()=>{if(!live.member||!features.study||document.hidden)return;try{await orbitApi('study_tick',{id:features.study.id,finish:false});}catch(e){features.study=null;toast('Registro de tempo interrompido: '+e.message);}},15000);
let expiringRun=false;
setInterval(async()=>{const r=features.run;if(!live.member||!r||r.status!=='active')return;const seconds=Math.max(0,Math.ceil((Date.parse(r.ends_at)-Date.now())/1000));const el=$('#runClock');if(el)el.textContent='Restam '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');if(!seconds&&!expiringRun&&features.players.some(p=>p.run_id===r.id&&p.user_id===live.user.id)){expiringRun=true;try{await orbitApi('run_finish',{id:r.id});await refreshRun();await loadFeatures();render();}catch(e){toast('Atualize a prova para concluir a correção.');}finally{expiringRun=false;}}},1000);
const oldLogout=logoutOnline;
logoutOnline=async function(){await stopPresence();timerEngaged=false;features.study=null;features.run=null;features.overview=null;features.documents=[];features.messages=[];$('#communitychat').classList.add('hidden');await oldLogout();};

// Session timestamps are generated on the server, never supplied by clients.
joinSession=async function(room){if(!live.member)return;await guarded(async()=>{const current=live.sessions.find(s=>s.user_id===live.user.id);await orbitApi(current?.room===room?'session_leave':'session_join',{room});await refreshSessions();render();});};
function avatar(id){return `<span class="avatar">${features.avatarUrls[id]?`<img src="${esc(features.avatarUrls[id])}" alt="">`:esc(person(id).slice(0,2))}</span>`;}
function uploadAvatar(){formModal('Foto de perfil','PNG, JPEG, WebP ou GIF, até 5 MB. Visível aos participantes.', '<label class="field">Imagem<input name="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif" required></label>',async(p,f)=>{const file=f.elements.image.files[0];if(file.size>5242880||!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Escolha uma imagem PNG, JPEG ou WebP de até 5 MB.');const path=live.user.id+'/avatar/'+crypto.randomUUID();await checked(db.storage.from('orbit-uploads').upload(path,file,{contentType:file.type}));await checked(db.from('orbit_profiles').update({avatar_path:path}).eq('user_id',live.user.id));const old=live.profile.avatar_path;live.profile.avatar_path=path;await refreshSessions();if(old)await db.storage.from('orbit-uploads').remove([old]);});}
function toggleLibraryLayout(){features.libraryLayout=features.libraryLayout==='grid'?'list':'grid';render();}
function filterCollection(id){features.collection=id;render();}
function editCollection(id){const d=byId(id);formModal('Coleção','Agrupe os materiais da biblioteca na sua conta.',field('title','Nome',d?.title,'text','required maxlength="200"')+area('text','Descrição',d?.data.text),p=>orbitApi('document_save',{id,kind:'collection',title:p.title,data:{...d?.data,text:p.text,ids:d?.data.ids||[]}}));}
function addToCollection(material){if(!myDocuments('collection').length){editCollection();toast('Crie a coleção e depois adicione o material.');return;}formModal('Adicionar à coleção','O material continua disponível na biblioteca.',selectField('collection','Coleção',myDocuments('collection').map(d=>[d.id,d.title]),''),async p=>{const d=byId(p.collection);await orbitApi('document_save',{id:d.id,kind:'collection',title:d.title,data:{...d.data,ids:[...new Set([...(d.data.ids||[]),material])]}});});}
function highlightSelection(){const text=window.getSelection()?.toString();const field=$('#materialProgress')?.elements.highlight;if(field&&text){field.value=text;toast('Trecho adicionado. Salve o progresso para guardá-lo.');}else toast('Selecione um trecho do texto antes de destacar.');}
function layoutIslandPeople(){const container=$('#islandPeople');const width=container.clientWidth;if(!width)return;container.querySelector('#islandMore')?.remove();const people=[...container.querySelectorAll('.island-person')];people.forEach(p=>p.hidden=false);const sizes=people.map(p=>p.getBoundingClientRect().width+10);if(sizes.reduce((a,b)=>a+b,0)<=width)return;let used=0,shown=0;for(let i=0;i<people.length;i++){const fits=used+sizes[i]<=width-50;people[i].hidden=!fits;if(fits){used+=sizes[i];shown++;}}const more=document.createElement('button');more.id='islandMore';more.className='island-more';more.textContent='+'+(people.length-shown);more.setAttribute('aria-label','Ver todos os participantes da sessão');more.setAttribute('aria-expanded',String($('#islandPeopleTray').classList.contains('open')));more.onclick=()=>toggleIslandTray('islandPeopleTray',more);container.append(more);}
if(typeof ResizeObserver!=='undefined')new ResizeObserver(layoutIslandPeople).observe($('#islandPeople'));

let completedFocusCycles=0;
function onOnlineTimerEnd(){if(!live.member)return;const wasFocus=timerMode==='focus';if(wasFocus)completedFocusCycles++;const next=wasFocus?(completedFocusCycles%4===0?'long':'short'):'focus';modal(wasFocus?'Bloco concluído':'Pausa concluída',next==='long'?'Quatro ciclos concluídos. Faça uma pausa longa.':'Confirme quando estiver pronto para a próxima etapa.',actionButton(next==='focus'?'Iniciar foco':next==='long'?'Pausa de 15 minutos':'Pausa de 5 minutos','beginNextTimer',[next],'primary')+actionButton('Agora não','closeModal',[],'mt'));}
function beginNextTimer(mode){closeModal();setTimer(mode);toggleTimer();refreshIsland();}

/* Símbolos visuais de progresso e patentes do Orbit. */
// Desenhos e tamanhos do HTML de referência aprovado.
const approvedRanks=[
 {name:'Quartzo',slug:'quartzo',colors:['#f7f6ff','#c4bfd9','#817b9e'],outline:'#807997',halo:'#c8c3dd35',shadow:'#847f9e25',desc:'Cristal alongado · Branco translúcido',shape:'M32 5 47 20 45 48 32 59 19 48 17 20Z',facets:'M32 5V59M17 20 32 27 47 20M19 48 32 40 45 48'},
 {name:'Ametista',slug:'ametista',colors:['#e7c8ff','#ac72ea','#6535ad'],outline:'#794bb3',halo:'#a970e829',shadow:'#8b4dc330',desc:'Cristal lapidado · Violeta',shape:'M32 5 47 20 47 44 32 59 17 44 17 20Z',facets:'M32 5 25 23 17 20M32 5 39 23 47 20M25 23H39V41H25ZM17 44 25 41 32 59 39 41 47 44'},
 {name:'Diamante',slug:'diamante',colors:['#d9faff','#80caed','#387bbd'],outline:'#428bb9',halo:'#6cc8e827',shadow:'#4395c42a',desc:'Corte amplo · Azul cristalino',shape:'M17 12 47 12 59 27 32 57 5 27Z',facets:'M5 27H59M17 12 23 27 32 57 41 27 47 12M23 27 32 12 41 27'},
 {name:'Astralita',slug:'astralita',colors:['#ed9de9','#a9a5ff','#81eadc'],outline:'#9b78ce',halo:'#a891f33a',shadow:'#ad84d135',desc:'Cristal estelar · Reflexos iridescentes',shape:'M32 3 42 21 60 32 42 43 32 61 22 43 4 32 22 21Z',facets:'M32 3V61M4 32H60M22 21 42 43M42 21 22 43'}
];let symbolSerial=0;
function approvedRankSVG(r,size){
 const id='gem'+symbolSerial++,mini=size<=24,large=size>=100;
 const simple={quartzo:'M32 5V59',ametista:'M32 5V59',diamante:'M5 27H59',astralita:''};
 const detail={quartzo:'M32 5 47 20 32 27Z',ametista:'M25 23H39V41H25Z',diamante:'M17 12 32 12 23 27 5 27Z',astralita:'M32 3 42 21 32 32 22 21Z'};
 return `<svg xmlns="http://www.w3.org/2000/svg" class="badge" width="${size}" height="${size}" viewBox="0 0 64 64" role="img" aria-label="Patente ${r.name}">
 <defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${r.colors[0]}"/><stop offset=".48" stop-color="${r.colors[1]}"/><stop offset="1" stop-color="${r.colors[2]}"/></linearGradient>
 ${large?`<clipPath id="${id}clip"><path d="${r.shape}"/></clipPath><linearGradient id="${id}sweep"><stop stop-color="white" stop-opacity="0"/><stop offset=".5" stop-color="white" stop-opacity=".55"/><stop offset="1" stop-color="white" stop-opacity="0"/></linearGradient>`:''}</defs>
 <path d="${r.shape}" fill="url(#${id})" stroke="${r.outline}" stroke-width="${mini?2.3:1.8}" stroke-linejoin="round"/>
 <path d="${mini?simple[r.slug]:r.facets}" fill="none" stroke="${r.outline}" opacity="${mini?.55:.6}" stroke-width="${mini?2.4:1.25}" stroke-linejoin="round"/>
 ${r.slug==='astralita'&&!mini?'<path d="M32 20 36 28 44 32 36 36 32 44 28 36 20 32 28 28Z" fill="#fff" opacity=".6"/>':''}
 ${large?`<style>@keyframes orbit-sweep{0%,15%{transform:translateX(-45px)}65%,100%{transform:translateX(95px)}}.light-sweep{animation:orbit-sweep 6s cubic-bezier(.4,0,.2,1) infinite}@media(prefers-reduced-motion:reduce){.light-sweep{animation:none;opacity:0}}</style><path d="${detail[r.slug]}" fill="white" opacity=".18"/><path d="${r.shape}" transform="translate(32 32) scale(.92) translate(-32 -32)" fill="none" stroke="white" stroke-opacity=".3" stroke-width=".7" stroke-linejoin="round"/><g clip-path="url(#${id}clip)"><g class="light-sweep"><path d="M-22-8H-4L28 72H10Z" fill="url(#${id}sweep)"/></g></g>`:''}</svg>`
}

const approvedIndicators=[
{name:'Orbes',slug:'orbes',colors:['#ffe7aa','#efba62','#cd7953'],halo:'#efba6228',shadow:'#ca8c4028',desc:'Moedas · Núcleo luminoso',label:'RECOMPENSA'},
{name:'PR',slug:'pr',colors:['#cebaff','#9b7ce9','#6552d1'],halo:'#a18aee28',shadow:'#6552d128',desc:'Pontos de Rank · Avanço competitivo',label:'COMPETIÇÃO'},
{name:'XP',slug:'xp',colors:['#77e1ae','#42bdb8','#438dd8'],halo:'#54c4b526',shadow:'#42bdb828',desc:'Experiência · Progresso acumulado',label:'EVOLUÇÃO'},
{name:'Sinapse',slug:'sinapse',colors:['#ffd36b','#f69a44','#e96858'],halo:'#ee9e5028',shadow:'#e8914428',desc:'Intensidade · Raio de energia',label:'ATIVIDADE'}
];
function approvedIndicatorSVG(r,size){
 const id='ind'+symbolSerial++,mini=size<=24,large=size>=100,g=`url(#${id})`;
 let shape='',detail='';
 if(r.slug==='orbes'){
 shape=`<circle cx="32" cy="32" r="23" fill="${g}"/>`;
 detail=`<path d="M32 20Q34 29 44 32Q34 35 32 44Q30 35 20 32Q30 29 32 20Z" fill="white" opacity=".72"/>`;
 }else if(r.slug==='pr'){
 shape=`<path d="M16 27 32 13 48 27M16 47 32 33 48 47" fill="none" stroke="${g}" stroke-width="11" stroke-linejoin="round" stroke-linecap="round"/>`;
 }else if(r.slug==='xp'){
 shape=`<path d="M32 13A19 19 0 1 0 51 32" fill="none" stroke="${g}" stroke-width="12" stroke-linecap="round"/><circle cx="46" cy="18" r="6" fill="${r.colors[2]}"/>`;
 }else{
 shape=`<path d="M35 7C37 4 41 6 40 9L35 25H48C51 25 52 28 50 30L27 57C25 60 21 58 22 55L27 39H14C11 39 10 36 12 34Z" fill="${g}"/>`;
 }
 return `<svg xmlns="http://www.w3.org/2000/svg" class="badge" width="${size}" height="${size}" viewBox="0 0 64 64" role="img" aria-label="${r.name}"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${r.colors[0]}"/><stop offset=".5" stop-color="${r.colors[1]}"/><stop offset="1" stop-color="${r.colors[2]}"/></linearGradient>${large?`<mask id="${id}mask" maskUnits="userSpaceOnUse" x="0" y="0" width="64" height="64" style="mask-type:alpha">${shape}</mask><linearGradient id="${id}sweep"><stop stop-color="white" stop-opacity="0"/><stop offset=".5" stop-color="white" stop-opacity=".55"/><stop offset="1" stop-color="white" stop-opacity="0"/></linearGradient>`:''}</defs>${shape}${detail}${large?`<style>@keyframes orbit-sweep{0%,15%{transform:translateX(-45px)}65%,100%{transform:translateX(95px)}}.light-sweep{animation:orbit-sweep 6s cubic-bezier(.4,0,.2,1) infinite}@media(prefers-reduced-motion:reduce){.light-sweep{animation:none;opacity:0}}</style><g mask="url(#${id}mask)"><g class="light-sweep"><path d="M-22-8H-4L28 72H10Z" fill="url(#${id}sweep)"/></g></g>`:''}</svg>`;
}

function identityIcon(kind,size=24){
 const slug=kind==='synapse'?'sinapse':kind;
 const symbol=approvedIndicators.find(item=>item.slug===slug);
 if(!symbol)return '';
 return approvedIndicatorSVG(symbol,size).replace('class="badge"',`class="identity-icon identity-${kind}"`);
}
function rankMark(tier,size='small'){
 const n=Math.max(0,Math.min(3,Number(tier)||0));
 const pixels=typeof size==='number'?size:({tiny:16,small:24,guide:48,large:144}[size]||24);
 const cls=typeof size==='number'?'size-'+size:size;
 return approvedRankSVG(approvedRanks[n],pixels).replace('class="badge"',`class="rank-mark rank-${n} rank-${cls}"`);
}
function rankingAvatar(profile){const name=profile.display_name||'Enemizade';const image=features.avatarUrls[profile.user_id];return `<span class="avatar ranking-avatar">${image?`<img src="${esc(image)}" alt="">`:esc(name.slice(0,2).toUpperCase())}</span>`;}
function identityStat(label,value,sub,kind){return `<div class="stat identity-stat"><div class="statlabel">${kind==='rank'?rankMark(value.tier,'tiny'):identityIcon(kind)}${esc(label)}</div><strong>${esc(kind==='rank'?tierNames[value.tier]:value)}</strong><small>${esc(sub)}</small></div>`;}
progression=function(){const s=features.overview?.stats;if(!s)return '';return `<div class="grid4 mb">${identityStat('Nível',s.level,fmt(s.xp)+' XP permanente','xp')}${identityStat('Patente',s,fmt(s.act_pr)+' PR no ato','rank')}${identityStat('Sinapse',s.synapse+'%','Máximo: '+Math.round(s.best_synapse)+'%','synapse')}${identityStat('PR da temporada',fmt(s.pr),s.correct+' acertos','pr')}</div>`;};
function rankingRow(r,i){const s=r.stats,q=s.correct+s.wrong,accuracy=q?Math.round(100*s.correct/q):0;const position=i<3?['1º','2º','3º'][i]:(i+1)+'º';return `<li class="ranking-player ${i<3?'podium-'+(i+1):''} ${r.profile.user_id===live.user.id?'ranking-me':''}"><span class="ranking-position">${position}</span><button class="ranking-person" onclick="${call('viewMember',r.profile.user_id)}">${rankingAvatar(r.profile)}<span class="ranking-name"><strong>${esc(r.profile.display_name)}</strong><small>${rankMark(s.tier,'tiny')} ${esc(tierNames[s.tier])} · nível ${s.level}</small></span></button><span class="ranking-activity">${q} ${q===1?'questão':'questões'} · ${accuracy}% de acerto</span><span class="ranking-score">${identityIcon('pr')} <strong>${fmt(s.pr)}</strong><small>PR</small></span></li>`;}
function rankingOnline(){const sorted=[...features.overview.ranks].sort((a,b)=>b.stats.pr-a.stats.pr||b.stats.xp-a.stats.xp||a.profile.user_id.localeCompare(b.profile.user_id));const leader=sorted[0];const my=sorted.find(r=>r.profile.user_id===live.user.id);const totals=sorted.reduce((a,r)=>({questions:a.questions+r.stats.correct+r.stats.wrong,correct:a.correct+r.stats.correct,wrong:a.wrong+r.stats.wrong,pr:a.pr+Number(r.stats.pr)}),{questions:0,correct:0,wrong:0,pr:0});return head('Ranking','Acompanhe a temporada e a evolução das suas enemizades.')+`<div class="ranking-layout"><div class="stack"><section class="card ranking-champion"><div class="sectionhead"><div><h2>Campeão atual</h2><p>Liderança da temporada</p></div>${icon('trophy')}</div>${leader?`<button class="champion-profile" onclick="${call('viewMember',leader.profile.user_id)}">${rankingAvatar(leader.profile)}<span><strong>${esc(leader.profile.display_name)}</strong><small>${rankMark(leader.stats.tier,'tiny')} ${tierNames[leader.stats.tier]} · nível ${leader.stats.level}</small></span></button><div class="champion-score">${identityIcon('pr')} <strong>${fmt(leader.stats.pr)}</strong> <span>PR</span></div>`:empty('Ainda não há participantes no ranking.')}</section><section class="card"><div class="sectionhead"><div><h2>Ranking</h2><p>Ordenado pelo PR da temporada</p></div></div><ol class="ranking-list">${sorted.map(rankingRow).join('')||empty('Ainda não há participantes.')}</ol></section><section class="card"><div class="sectionhead"><div><h2>Estatísticas gerais</h2><p>Participantes autorizados com perfil</p></div></div><div class="grid4">${stat('Enemizades',sorted.length,'','users')}${stat('Questões',totals.questions,'','book')}${stat('Acertos',totals.correct,'','check')}${identityStat('PR',fmt(totals.pr),'Na temporada','pr')}</div></section></div><aside class="stack"><section class="card"><h2>Minha posição</h2>${my?`<div class="my-rank mt"><span class="ranking-position">${sorted.indexOf(my)+1}º</span>${rankingAvatar(my.profile)}<div><strong>${esc(my.profile.display_name)}</strong><small>${rankMark(my.stats.tier,'tiny')} ${tierNames[my.stats.tier]} · nível ${my.stats.level}</small></div></div><div class="ranking-metrics mt"><span>${identityIcon('pr')} <b>${fmt(my.stats.pr)}</b> PR</span><span>${identityIcon('xp')} <b>${fmt(my.stats.xp)}</b> XP</span><span>${identityIcon('synapse')} <b>${my.stats.synapse}%</b> Sinapse</span></div>`:empty('Seu perfil ainda não está no ranking.')}</section><section class="card"><h2>Patentes</h2><div class="rank-guide-list">${tierNames.map((name,i)=>`<div>${rankMark(i,'guide')}<span>${name}</span></div>`).join('')}</div></section></aside></div>${features.overview.config.provisional_thresholds?'<p class="notice mt">Limiares intermediários de patentes em teste: 2.000 e 7.000 PR. Astralita: 12.000 PR no ato.</p>':''}`;}
views.ranking=rankingOnline;
const orbesCounter=$('#orbesCounter');if(orbesCounter)orbesCounter.innerHTML=identityIcon('orbes')+'<span aria-hidden="true">—</span><span class="orbes-name">Orbes</span>';
let timerEngaged=false;
const priorToggleTimer=toggleTimer,priorResetTimer=resetTimer,priorSetTimer=setTimer;
toggleTimer=function(){priorToggleTimer();timerEngaged=true;refreshIsland();};
resetTimer=function(){priorResetTimer();timerEngaged=false;refreshIsland();};
setTimer=function(mode){priorSetTimer(mode);timerEngaged=false;refreshIsland();};
let presenceId=null,presenceCount=null,presencePoll=null,presenceEpoch=0;
function browserPresenceId(){if(presenceId)return presenceId;try{presenceId=localStorage.getItem('enemizades-orbit-device-id');if(!presenceId){presenceId=crypto.randomUUID();localStorage.setItem('enemizades-orbit-device-id',presenceId);}return presenceId;}catch(e){try{presenceId=crypto.randomUUID();return presenceId;}catch{return null;}}}
async function pulsePresence(){if(!live.member)return;const epoch=presenceEpoch,id=browserPresenceId();if(!id){presenceCount=null;refreshIsland();return;}try{const count=await checked(db.rpc('orbit_presence',{p_device:id,p_leave:false}));if(epoch!==presenceEpoch||!live.member)return;presenceCount=Number.isInteger(count)?count:null;}catch(e){if(epoch!==presenceEpoch)return;presenceCount=null;}refreshIsland();}
function startPresence(){presenceEpoch++;clearInterval(presencePoll);presenceCount=null;pulsePresence();presencePoll=setInterval(pulsePresence,30000);}
async function stopPresence(){presenceEpoch++;clearInterval(presencePoll);presencePoll=null;const id=presenceId;presenceCount=null;if(id&&live.member){try{await checked(db.rpc('orbit_presence',{p_device:id,p_leave:true}));}catch(e){/* O registro expira automaticamente se a conexão cair. */}}}
function updateIslandSummary(){if(!live.member)return;const el=$('#islandSummary');if(!el)return;const remaining=timerRunning?Math.max(0,Math.ceil((timerDeadline-Date.now())/1000)):timerRemaining;const active=timerEngaged||timerRunning||remaining<timerTotal;let content;
 if(islandNotice)content=`<span data-summary="online" class="island-notice" role="status">${icon('bell')}${esc(islandNotice)}</span>`;
 else if(active)content=`<span data-summary="online" class="island-timer-summary" aria-label="${timerMode==='focus'?'Estudo':'Descanso'} · ${islandTime(remaining)}${timerRunning?'':' · pausado'}">${icon(timerMode==='focus'?'book':'coffee')}<b>${islandTime(remaining)}</b>${icon(timerRunning?'timer':'pause')}</span>`;
 else content=`<span data-summary="online" class="connections" title="${presenceCount===null?'Conexões indisponíveis':presenceCount+' conexões de navegadores ativas'}">${icon('link')}<b>${presenceCount===null?'—':presenceCount}</b></span><i class="island-divider" aria-hidden="true"></i><span class="studying" title="${live.sessions.length} pessoas em sessão">${icon('book')}<b>${live.sessions.length}</b></span>`;
 const key=JSON.stringify([islandNotice,active,active?remaining:null,timerMode,timerRunning,presenceCount,live.sessions.length]);if(el.dataset.summaryKey!==key||el.firstElementChild?.dataset.summary!=='online'){el.innerHTML=content;el.dataset.summaryKey=key;}
}
gate('Carregando acesso…');startOnline();
